WITH metrics AS (SELECT *, LAST_VALUE(country, TRUE) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, ROW_NUMBER() OVER w_running AS row_seq FROM sessions WHERE customer_id = 13 WINDOW w_running AS (PARTITION BY YEAR(started_at), device ORDER BY started_at DESC, id)) SELECT browser, COUNT(DISTINCT country) AS distinct_countries, ROUND(SUM(row_seq) / NULLIF(COUNT(CASE WHEN browser = 'Edge' THEN 1 END), 0), 2) AS row_seq_per_edge, COUNT(*) AS event_count, PERCENTILE_APPROX(row_seq, ARRAY(0.25, 0.5, 0.75)) AS row_seq_quartiles FROM metrics GROUP BY browser HAVING COUNT(*) >= 1 ORDER BY row_seq_per_edge NULLS LAST;
